window.KH_SURA(32, {"sura": "السجدة", "n": 32, "ayat": {"1": "الم", "2": "تَنْزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِنْ رَبِّ الْعَالَمِينَ", "3": "أَمْ يَقُولُونَ افْتَرَاهُ بَلْ هُوَ الْحَقُّ مِنْ رَبِّكَ لِتُنْذِرَ قَوْمًا مَا أَتَاهُمْ مِنْ نَذِيرٍ مِنْ قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ", "4": "اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ مَا لَكُمْ مِنْ دُونِهِ مِنْ وَلِيٍّ وَلَا شَفِيعٍ أَفَلَا تَتَذَكَّرُونَ", "5": "يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ", "6": "ذَلِكَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيزُ الرَّحِيمُ", "7": "الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ وَبَدَأَ خَلْقَ الْإِنْسَانِ مِنْ طِينٍ", "8": "ثُمَّ جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَاءٍ مَهِينٍ", "9": "ثُمَّ سَوَّاهُ وَنَفَخَ فِيهِ مِنْ رُوحِهِ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَا تَشْكُرُونَ", "10": "وَقَالُوا أَإِذَا ضَلَلْنَا فِي الْأَرْضِ أَإِنَّا لَفِي خَلْقٍ جَدِيدٍ بَلْ هُمْ بِلِقَاءِ رَبِّهِمْ كَافِرُونَ", "11": "قُلْ يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ ثُمَّ إِلَى رَبِّكُمْ تُرْجَعُونَ", "12": "وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُو رُءُوسِهِمْ عِنْدَ رَبِّهِمْ رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَالِحًا إِنَّا مُوقِنُونَ", "13": "وَلَوْ شِئْنَا لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا وَلَكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ", "14": "فَذُوقُوا بِمَا نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَذَا إِنَّا نَسِينَاكُمْ وَذُوقُوا عَذَابَ الْخُلْدِ بِمَا كُنْتُمْ تَعْمَلُونَ", "15": "إِنَّمَا يُؤْمِنُ بِآيَاتِنَا الَّذِينَ إِذَا ذُكِّرُوا بِهَا خَرُّوا سُجَّدًا وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ", "16": "تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ", "17": "فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ", "18": "أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا لَا يَسْتَوُونَ", "19": "أَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ جَنَّاتُ الْمَأْوَى نُزُلًا بِمَا كَانُوا يَعْمَلُونَ", "20": "وَأَمَّا الَّذِينَ فَسَقُوا فَمَأْوَاهُمُ النَّارُ كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا وَقِيلَ لَهُمْ ذُوقُوا عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ", "21": "وَلَنُذِيقَنَّهُمْ مِنَ الْعَذَابِ الْأَدْنَى دُونَ الْعَذَابِ الْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ", "22": "وَمَنْ أَظْلَمُ مِمَّنْ ذُكِّرَ بِآيَاتِ رَبِّهِ ثُمَّ أَعْرَضَ عَنْهَا إِنَّا مِنَ الْمُجْرِمِينَ مُنْتَقِمُونَ", "23": "وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ وَجَعَلْنَاهُ هُدًى لِبَنِي إِسْرَائِيلَ", "24": "وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ", "25": "إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ", "26": "أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ مِنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ أَفَلَا يَسْمَعُونَ", "27": "أَوَلَمْ يَرَوْا أَنَّا نَسُوقُ الْمَاءَ إِلَى الْأَرْضِ الْجُرُزِ فَنُخْرِجُ بِهِ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَامُهُمْ وَأَنْفُسُهُمْ أَفَلَا يُبْصِرُونَ", "28": "وَيَقُولُونَ مَتَى هَذَا الْفَتْحُ إِنْ كُنْتُمْ صَادِقِينَ", "29": "قُلْ يَوْمَ الْفَتْحِ لَا يَنْفَعُ الَّذِينَ كَفَرُوا إِيمَانُهُمْ وَلَا هُمْ يُنْظَرُونَ", "30": "فَأَعْرِضْ عَنْهُمْ وَانْتَظِرْ إِنَّهُمْ مُنْتَظِرُونَ"}, "units": [{"aya": 5, "title": "في المعنى بقوله: ﴿ثم يعرج إليه في يوم كان مقداره ألف سنة مما تعدون﴾", "tabari": {"page": "18/592", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك عندى بالصواب قول من قال: معناه: يدبر الأمر من السماء إلى الأرض، ثم يعرج إليه في يوم كان مقدار ذلك اليوم في عروج ذلك الأمر إليه، ونزوله إلى الأرض، ألف سنة مما تعدون من أيامكم؛ خمسمائة في النزول، وخمسمائة في الصعود؛ لأن ذلك أظهر معانيه، وأشبهها بظاهر التنزيل.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: إن الأمر ينزل من السماء إلى الأرض، ويصعد من الأرض إلى السماء في يوم واحد، وقدر ذلك ألف سنة مما تعدون من أيام الدنيا؛ لأن ما بين الأرض إلى السماء خمسمائة عام، وما بين السماء إلى الأرض مثل ذلك، فذلك ألف سنة", "taqdim": 0, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["الضحاك", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [61254, 61255, 61259, 61260, 61261, 61262, 61264, 61265, 61266, 61267, 61268, 61272, 61273]}, {"n": 2, "t": "بل معنى ذلك: يدبر الأمر من السماء إلى الأرض، ثم يعرج إليه، في يوم من الأيام الستة، التي خلق الله فيهن الخلق، كان مقدار ذلك اليوم ألف سنة مما تعدون من أيامكم", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"]], "athar": [61254, 61259, 61260, 61261, 61262]}, {"n": 3, "t": "بل معني ذلك: يدبر الأمر من السماء إلى الأرض بالملائكة، ثم تعرج إليه الملائكة في يوم كان مقداره ألف سنة من أيام الدنيا", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"]], "athar": [61254, 61259, 61260, 61261, 61262]}, {"n": 4, "t": "بل معنى ذلك: يدبر الأمر من السماء إلى الأرض في يوم، كان مقدار ذلك التدبير ألف سنة ﴿مما تعدون﴾ من أيام الدنيا، ثم يعرج إليه ذلك التدبير الذي دبره", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 5, "t": "بل معنى ذلك: يدبر الأمر من السماء إلى الأرض، ثم يعرج إلى الله في يوم كان [مقداره ألف سنة ، مقدار العروج ألف سنة مما تعدون", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [61278]}]}, "mawaqif": [{"taliq": 5159, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 67 بتصرف", "qawl": "مجاهد من", "nass": "فالمعنى أن الأمور تنفذ عند الله تعالى لهذه المدة، ثم تصير إليه آخرا؛ لأن عاقبة الأمور إليه", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["032_001_1.png", "032_001_2.png"], "pages": [414, 415], "n": 5, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5159, "masala": "معنى: {ثم يعرج إليه في يوم كان مقداره ألف سنة مما تعدون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "معناه أن الأمر ينزل من السماء إلى الأرض، ويصعد من الأرض إلى السماء في يوم واحد، وقدر ذلك ألف سنة مما تعدون من أيام الدنيا، لأن ما بين الأرض إلى السماء خمس مائة عام، وما بين السماء إلى الأرض مثل ذلك، فذلك ألف سنة", "ashab": "", "athar": []}, {"n": 2, "t": "يدبر الأمر من السماء إلى الأرض، ثم يعرج إليه في يوم من الأيام الستة التي خلق الله فيهن الخلق، وكل يوم من هذه كألف سنة مما تعدون من أيامكم", "ashab": "", "athar": []}, {"n": 3, "t": "يدبر الأمر من السماء إلى الأرض بالملائكة، تم تعرج إليه الملائكة في يوم كان مقداره ألف سنة من أيام الدنيا", "ashab": "", "athar": []}, {"n": 4, "t": "يدبر الأمر من السماء إلى الأرض في يوم، كان مقدار ذلك التدبير ألف سنة مما تعدون من أيام الدنيا، ثم يعرج إليه ذلك التدبير الذي دبره", "ashab": "", "athar": []}, {"n": 5, "t": "يدبر الأمر من السماء إلى الأرض، ثم يعرج إلى الله في يوم كان مقداره ألف سنة، مقدار العروج ألف سنة مما تعدون", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "معنى: {ثم يعرج إليه في يوم كان مقداره ألف سنة مما تعدون}", "mawsua": {"taliq": 5159, "masala": "معنى: {ثم يعرج إليه في يوم كان مقداره ألف سنة مما تعدون}", "sigha": "ذكر قولين", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "أن التدبير المنقضي في يوم القيامة ألف سنة لو دبره البشر", "ashab": "", "athar": []}, {"n": 2, "t": "أن الله تعالى يدبر ويلقي إلى الملائكة أمور ألف سنة من عدنا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5159, "mi": 2, "aya": 5, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "الرابع", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5159, "mi": 2, "aya": 5, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 596", "qawl": "الأول", "nass": "لأن ذلك أظهر معانيه، وأشبهها بظاهر التنزيل", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5159, "mi": 2, "aya": 5, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 68", "qawl": "الثاني", "nass": "وهذا قول ضعيف مكرهة ألفاظ هذه الآية عليه، رادة له الأحاديث التي تثبت أيام خلق الله تعالى المخلوقات", "qawaid": ["القرآن والنظائر", "السنة"], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]], "2": [["ابن عطية", "d"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {"ابن عطية": ["القرآن والنظائر", "السنة"]}}}, {"aya": 7, "title": "في معنى ذلك ﴿الذي أحسن كل شيء خلقه﴾", "tabari": {"page": "18/597", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك عندى بالصواب على قراءة من قرأه: ﴿الذي أحسن كل شيء خلقه﴾. بفتح اللام قول من قال: معناه أحكم وأتقن؛ لأنه لا معنى لذلك إذ قرئ كذلك إلا أحد وجهين؛ إما هذا الذي قلنا من معنى الإحكام والإتقان، أو معنى التحسين الذي هو في معنى الجمال والحسن، فلما كان في خلقه ما لا يشك في قبحه وسماجته، علم أنه لم يعن به أنه حسن كل ما خلق، ولكن معناه أنه أحكمه وأتقن صنعته. وأما على القراءة الأخرى التي هي بتسكين اللام، فإن أولى تأويلاته به قول من قال: معنى ذلك: أعلم [وألهم] كل شيء خلقه هو أحسنهم، كما قال: ﴿قال ربنا الذي أعطى كل شيء خلقه ثم هدى﴾ [طه: ٥٠]؛ لأن ذلك أظهر معانيه.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: وأتقن كل شيء وأحكمه", "taqdim": 0, "n_athar": 4, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [61282, 61283, 61284, 61285, 61286, 61287, 61288, 61289, 61290, 61296]}, {"n": 2, "t": "بل معنى ذلك: الذي حسن خلق كل شيء", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [61292, 61297]}, {"n": 3, "t": "بل معنى ذلك: أعلم كل شيء خلقه. كأنهم وجهوا تأويل الكلام إلى أنه ألهم خلقه ما يحتاجون إليه، وأن قوله: ﴿أحسن﴾. إنما هو من قول القائل: فلان يحسن كذا. إذا كان يعلمه", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [61288, 61289, 61290, 61296]}]}, "mawaqif": [{"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 69", "qawl": "الأول", "nass": "فهو حسن من جهة ما هو لمقاصده التي أريد لها", "qawaid": [], "tabi": ""}, {"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "18/ 599 - 600", "qawl": "الثاني", "nass": "وأما الذي وجه تأويل ذلك إلى أنه بمعنى: الذي أحسن خلق كل شيء، فإنه جعل الخلق نصبا بمعنى التفسير، كأنه قال: الذي أحسن كل شيء خلقا منه. وقد كان بعضهم يقول: هو من المقدم الذي معناه التأخير", "qawaid": [], "tabi": ""}, {"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن كثير", "fil": "وجهه", "kind": "توجيه", "ref": "11/ 92", "qawl": "", "nass": "كأنه جعله من المقدم والمؤخر", "qawaid": [], "tabi": ""}, {"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "18/ 598 - 599", "qawl": "الثالث", "nass": "كأنهم وجهوا تأويل الكلام إلى أنه ألهم خلقه ما يحتاجون إليه، وأن قوله: {أحسن} إنما هو من قول القائل: فلان يحسن كذا، إذا كان يعلمه … وعلى هذا القول،", "qawaid": [], "tabi": ""}, {"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 599", "qawl": "الأول", "nass": "لأنه لا معنى لذلك إذ قرئ كذلك إلا أحد وجهين؛ إما هذا الذي قلنا من معنى الإحكام والإتقان، أو معنى التحسين الذي هو في معنى الجمال والحسن؛ فلما كان في خلقه ما لا يشك في قبحه وسماجته علم أنه لم يعن به أنه حسن كل ما خلق، ولكن معناه أنه أحكمه وأتقن صنعته", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5161, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "الثالث", "nass": "وهذا قول فيه بعد", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["032_002_1.png"], "pages": [415], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5161, "masala": "معنى: {الذي أحسن كل شيء خلقه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أتقن كل شيء وأحكمه", "ashab": "", "athar": []}, {"n": 2, "t": "الذي حسن خلق كل شيء. وهذان القولان على قراءة من قرأ بفتح اللام", "ashab": "", "athar": []}, {"n": 3, "t": "أعلم كل شيء خلقه. وهذا القول على قراءة من قرأ بتسكين اللام", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]], "3": [["ابن جرير", "w"], ["ابن عطية", "d"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]], "3": [["ابن جرير", "w"], ["ابن عطية", "d"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 7, "title": "قراءة قوله تعالى: {خلقه}", "mawsua": {"taliq": 5160, "masala": "قراءة قوله تعالى: {خلقه}", "sigha": "خلاف مصرَّح به", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "بسكون اللام", "ashab": "", "athar": []}, {"n": 2, "t": "بفتح اللام", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5160, "mi": 0, "aya": 7, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 597", "qawl": "", "nass": "والصواب من القول في ذلك عندي أن يقال: إنهما قراءتان مشهورتان، قد قرأ بكل واحدة منهما علماء من القرأة، صحيحتا المعنى، وذلك أن الله أحكم خلقه، وأحكم كل شيء خلقه، فبأيتهما قرأ القارئ فمصيب", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "تأويل: ﴿إنما يؤمن بآياتنا الذين إذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون﴾", "tabari": {"page": "18/608", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ما يصدق بحججنا وآيات كتابنا إلا القوم الذين إذا ذكروا بها ووعظوا ﴿خروا﴾ لله ﴿سجدا﴾ لوجوههم؛ تذللا له ، واستكانة لعظمته، وإقرارا له بالعبودية، ﴿وسبحوا بحمد ربهم﴾. يقول: وسبحوا الله في سجودهم بحمده، فيبرئونه مما يصفه أهل الكفر به، ويضيفون إليه من الصاحبة والأولاد والشركاء والأنداد، ﴿وهم لا يستكبرون﴾. يقول: يفعلون ذلك، وهم لا يستكبرون عن السجود له والتسبيح، و لا يستنكفون عن التذلل له", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن هذه الآية نزلت على رسول الله ﷺ؛ لأن قوما من المنافقين كانوا الله يخرجون من المسجد إذا أقيمت الصلاة. ذكر ذلك عن حجاج، عن ابن جريج", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5168, "mi": 1, "aya": 16, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 76", "qawl": "الأول", "nass": "وكانت الجاهلية ينامون في أول الغروب، ومن أي وقت شاء الإنسان، فجاء انتظار وقت العشاء الآخرة غريبا شاقا", "qawaid": [], "tabi": ""}, {"taliq": 5168, "mi": 1, "aya": 16, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "18/ 613 بتصرف", "qawl": "", "nass": "الله وصف هؤلاء القوم بأن جنوبهم تنبو عن مضاجعهم، شغلا منهم بدعاء ربهم، وعبادته خوفا وطمعا، وذلك نبو جنوبهم عن المضاجع ليلا؛ لأن المعروف من وصف الواصف رجلا بأن جنبه نبا عن مضجعه، إنما هو وصف منه له بأنه جفا عن النوم في وقت منام الناس المعروف، وذلك الليل دون النهار، وكذلك تصف العرب الرجل إذا وصفته بذلك … فإذا كان ذلك كذلك، وكان الله -تعالى ذكره- لم يخصص في وصفه هؤلاء القوم بالذي وصفهم به من جفاء جنوبهم عن مضاجعهم من أحوال الليل وأوقاته حالا ووقتا دون حال ووقت؛ كان واجبا أن يكون ذلك على كل آناء الليل وأوقاته، وإذا كان كذلك كانت جميع الأقوال داخلة في ظاهر قوله: {تتجافى جنوبهم عن المضاجع}؛ لأن جنبه قد جفا عن مضجعه في الحال التي قام فيها للصلاة؛ قائما صلى، أو ذكر الله، أو قاعدا بعد أن لا يكون مضطجعا، وهو على القيام أو القعود قادر", "qawaid": ["اللغة", "السنة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5168, "mi": 1, "aya": 16, "alam": "ابن عطية", "fil": "ووافقه", "kind": "موافقة", "ref": "7/ 76 - 77", "qawl": "", "nass": "وعلى هذا التأويل أكثر الناس، وهو الذي فيه المدح، وفيه حديث عن النبي صلى الله عليه وسلم يذكر فيه قيام الليل ثم يستشهد بالآية … ورجح الزجاج هذا القول بأنهم جوزوا بإخفاء، فدل ذلك على أن العمل إخفاء أيضا، وهو قيام الليل", "qawaid": ["الدلالة العقلية"], "tabi": "ابن جرير"}], "mawsua": {"taliq": 5168, "masala": "معنى قوله تعالى: {تتجافى جنوبهم عن المضاجع}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هي الصلاة بين المغرب والعشاء، وأنها نزلت في قوم كانوا يصلون في ذلك الوقت", "ashab": "", "athar": []}, {"n": 2, "t": "عنى به صلاة المغرب", "ashab": "", "athar": []}, {"n": 3, "t": "عنى به انتظار صلاة العتمة", "ashab": "", "athar": []}, {"n": 4, "t": "عنى به قيام الليل", "ashab": "", "athar": []}, {"n": 5, "t": "أن هذه صفة قوم لا تخلو ألسنتهم من ذكر الله تعالى", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {"ابن عطية": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 16, "title": "في الصلاة التي وصفهم جل ثناؤه أن جنوبهم تتجافى لها عن المضطجع", "tabari": {"page": "18/609", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله وصف هؤلاء القوم بأن جنوبهم تنبو عن مضاجعهم، شغلا منهم [بدعاء ربهم، وعبادته] خوفا وطمعا، وذلك نبو جنوبهم عن المضاجع ليلا؛ لأن المعروف من وصف الواصف رجلا بأن جنبه نبا عن مضجعه، إنما هو وصف منه له بأنه جفا عن النوم في وقت منام الناس المعروف، وذلك الليل دون النهار، وكذلك تصف العرب الرجل إذا وصفته بذلك، يدل على ذلك قول عبد الله بن رواحة الأنصاري ﵁ في صفة نبي الله ﷺ.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي الصلاة بين المغرب والعشاء. وقال: نزلت هذه الآية في قوم كانوا يصلون في ذلك الوقت", "taqdim": 0, "n_athar": 5, "qailun": [["ابن أبي عروبة", ""], ["أنس", "صحابي"], ["أنس بن مالك", "صحابي"]], "athar": [61365, 61366, 61367, 61368, 61369, 61370, 61386, 61387, 61388]}, {"n": 2, "t": "عنى بها صلاة المغرب", "taqdim": 0, "n_athar": 1, "qailun": [["عطاء", "تابعي"]], "athar": [61395]}, {"n": 3, "t": "لانتظار صلاة العتمة", "taqdim": 0, "n_athar": 1, "qailun": [["أنس بن مالك", "صحابي"]], "athar": [61365, 61366, 61367, 61368, 61369, 61370, 61386, 61387, 61388]}, {"n": 4, "t": "عنى بها قيام الليل", "taqdim": 0, "n_athar": 3, "qailun": [["الحسن", "تابعي"], ["ابن زيد", "تابع التابعين"], ["مجاهد", "تابعي"]], "athar": [61380, 61381, 61391, 61394, 61403]}, {"n": 5, "t": "إنما هذه صفة قوم لا تخلو ألسنتهم من ذكر الله", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [61364, 61378, 61379, 61385]}]}, "mawaqif": [], "mushid": {"i": 3, "imgs": ["032_003_1.png"], "pages": [415], "n": 5, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "معنى: {ومما رزقناهم ينفقون}", "mawsua": {"taliq": 5169, "masala": "معنى: {ومما رزقناهم ينفقون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الزكاة المفروضة", "ashab": "", "athar": []}, {"n": 2, "t": "أنها النوافل والصدقات غير المفروضة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5169, "mi": 1, "aya": 16, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 77", "qawl": "الثاني", "nass": "وهذا القول أمدح", "qawaid": [], "tabi": ""}], "tags": {"m": {"2": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "قراءة قوله تعالى: {فلا تعلم نفس ما أخفي لهم من قرة أعين}", "mawsua": {"taliq": 5170, "masala": "قراءة قوله تعالى: {فلا تعلم نفس ما أخفي لهم من قرة أعين}", "sigha": "خلاف مصرَّح به", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "{أخفي} بضم الألف وفتح الياء، بمعنى: فعل", "ashab": "", "athar": []}, {"n": 2, "t": "أخفي» بضم الألف وإرسال الياء، بمعنى: أفعل؛ أخفي لهم أنا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5170, "mi": 0, "aya": 17, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 597", "qawl": "", "nass": "أخفي", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "نزول قوله تعالى: {أفمن كان مؤمنا كمن كان فاسقا لا يستوون}", "mawsua": {"taliq": 5171, "masala": "نزول قوله تعالى: {أفمن كان مؤمنا كمن كان فاسقا لا يستوون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها نزلت في علي بن أبي طالب?، والوليد بن عقبة ابن أبي معيط", "ashab": "", "athar": []}, {"n": 2, "t": "أنها نزلت في علي بن أبي طالب?، وعقبة بن أبي معيط", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5171, "mi": 1, "aya": 18, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 78 - 79", "qawl": "الأول", "nass": "وذلك يحتمل أن يكون في صدر إسلام الوليد لشيء كان في نفسه، أو لما روي من نقله عن بني المصطلق ما لم يكن حتى نزلت فيه: {يا أيها الذين آمنوا إن جاءكم فاسق بنبإ فتبينوا} [الحجرات: 6]. ويحتمل أيضا أن تطلق الشريعة ذلك عليه لأنه كان على طرف مما ينبغي، وهو الذي شرب الخمر في خلافة عثمان?، وصلى الصبح بالناس أربعا ثم التفت، وقال: أتريدون أن أزيدكم؟ ونحو هذا مما يطول ذكره", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 21, "title": "في معنى العذاب الأدنى، الذي وعد الله أن يذيقه هؤلاء الفسقة", "tabari": {"page": "18/626", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك أن يقال: إن الله وعد هؤلاء الفسقة المكذبين بوعيده في الدنيا العذاب الأدنى؛ أن يذيقهموه دون العذاب الأكبر. والعذاب: هو ما كان في الدنيا من بلاء أصابهم؛ إما شدة من مجاعة، أو قتل، أو مصائب يصابون بها، فكل ذلك من العذاب الأدنى. ولم يخصص الله تعالى ذكره، إذ وعدهم ذلك، أن يعذبهم بنوع من ذلك [دون نوع] ، وقد عذبهم بكل ذلك في الدنيا؛ بالقتل، والجوع، والشدائد، والمصائب في الأموال، فأوفى لهم بما وعدهم.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك مصائب الدنيا في الأنفس والأموال", "taqdim": 0, "n_athar": 9, "qailun": [["ابن عباس", "صحابي"], ["أبي بن كعب", "صحابي"], ["أبي العالية", "تابعي"], ["الحسن", "تابعي"], ["إبراهيم", "تابعي"]], "athar": [61458, 61459, 61464, 61465, 61467, 61468, 61469, 61474, 61475, 61476, 61484, 61491, 61492, 61493, 61495]}, {"n": 2, "t": "عنى بها الحدود", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [61464, 61465, 61491]}, {"n": 3, "t": "عنى بها القتل بالسيف. قال: وقتلوا يوم بدر", "taqdim": 0, "n_athar": 7, "qailun": [["عبد الله", "صحابي"], ["الحسن بن علي", "صحابي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [61460, 61461, 61462, 61463, 61464, 61465, 61466, 61470, 61471, 61477, 61482, 61483, 61485, 61489, 61490, 61491, 61494]}, {"n": 4, "t": "عنى بذلك سنون أصابتهم", "taqdim": 0, "n_athar": 2, "qailun": [["إبراهيم", "تابعي"]], "athar": [61468, 61469, 61493]}, {"n": 5, "t": "عنى بذلك عذاب القبر", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [61470, 61471, 61483]}, {"n": 6, "t": "ذلك عذاب الدنيا", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [61481, 61487]}]}, "mawaqif": [{"taliq": 5172, "mi": 1, "aya": 21, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 79", "qawl": "الثالث", "nass": "فيكون -على هذا التأويل- الراجع غير الذي يذوق، بل الذي يبقى بعده", "qawaid": [], "tabi": ""}, {"taliq": 5172, "mi": 1, "aya": 21, "alam": "ابن القيم", "fil": "وجه", "kind": "توجيه", "ref": "2/ 323", "qawl": "الخامس", "nass": "وقد احتج بهذه الآية جماعة -منهم: عبد الله بن عباس- على عذاب القبر، وفي الاحتجاج بها شيء؛ لأن هذا عذاب في الدنيا يستدعي به رجوعهم عن الكفر، ولم يكن هذا مما يخفى على حبر الأمة وترجمان القرآن، لكن من فقهه في القرآن ودقة فهمه فيه فهم منها عذاب القبر؛ فإنه سبحانه أخبر أن له فيه عذابين أدنى وأكبر، فأخبر أنه يذيقهم بعض الأدنى ليرجعوا، فدل على أنه بقي لهم من الأدنى بقية يعذبون بها بعد عذاب الدنيا، ولهذا قال: {من العذاب الأدنى}، ولم يقل: ولنذيقنهم العذاب الأدنى. فتأمله", "qawaid": [], "tabi": ""}, {"taliq": 5172, "mi": 1, "aya": 21, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 632", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك أن يقال: إن الله وعد هؤلاء الفسقة المكذبين بوعيده في الدنيا العذاب الأدنى، أن يذيقهموه دون العذاب الأكبر، والعذاب: هو ما كان في الدنيا من بلاء أصابهم؛ إما شدة من مجاعة، أو قتل، أو مصائب يصابون بها، فكل ذلك من العذاب الأدنى، ولم يخصص الله -تعالى ذكره- إذ وعدهم ذلك أن يعذبهم بنوع من ذلك دون نوع، وقد عذبهم بكل ذلك في الدنيا؛ بالقتل، والجوع، والشدائد، والمصائب في الأموال، فأوفى لهم بما وعدهم", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["032_004_1.png"], "pages": [415], "n": 6, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5172, "masala": "معنى العذاب الأدنى في قوله تعالى: {ولنذيقنهم من العذاب الأدنى}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه مصائب الدنيا في الأنفس والأموال", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الحدود", "ashab": "", "athar": []}, {"n": 3, "t": "أنه القتل بالسيف؛ كيوم بدر", "ashab": "", "athar": []}, {"n": 4, "t": "أنه سنون أصابتهم", "ashab": "", "athar": []}, {"n": 5, "t": "أنه عذاب القبر. السادس: أنه عذاب الدنيا", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن عطية", "w"]], "5": [["ابن القيم", "w"]]}, "t": {"3": [["ابن عطية", "w"]], "6": [["ابن القيم", "w"]]}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 22, "title": "تأويل: ﴿إنا من المجرمين منتقمون﴾", "tabari": {"page": "18/635", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿إنا من المجرمين منتقمون﴾. يقول: إنا من الذين اكتسبوا الآثام، واجترحوا السيئات - منتقمون.", "taqdim": 1, "n_athar": 2, "qailun": [["يزيد بن رفيع", ""], ["في حديثه", ""]], "athar": [61502]}, {"n": 2, "t": "ثنا محمد بن المبارك، قال: ثنا إسماعيل بن عياش ، قال: ثنا عبد العزيز بن عبيد الله، عن عبادة بن نسي، عن جنادة بن أبي أمية، عن معاذ بن جبل، قال: سمعت رسول الله ﷺ يقول: \"ثلاث من فعلهن فقد أجرم؛ من اعتقد لواء في غير حق، أو عق والديه، أو مشى مع ظالم ينصره فقد أجرم، يقول الله: ﴿إنا من المجرمين منتقمون﴾ \"", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 5, "imgs": ["032_005_1.png"], "pages": [416], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "معنى قوله تعالى: {فلا تكن في مرية من لقائه}", "mawsua": {"taliq": 5176, "masala": "معنى قوله تعالى: {فلا تكن في مرية من لقائه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "فلا تكن -يا محمد- في شك من لقاء موسى عليه السلام ربه تعالى", "ashab": "", "athar": []}, {"n": 2, "t": "فلا تكن في شك من لقاء موسى عليه السلام ليلة الإسراء", "ashab": "", "athar": []}, {"n": 3, "t": "فلا تكن في شك من لقاء الأذى كما لقي موسى عليه السلام الأذى", "ashab": "", "athar": []}, {"n": 4, "t": "فلا تكن في شك من تلقي موسى عليه السلام الكتاب", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5176, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 81", "qawl": "الثالث", "nass": "كأنه قال: ولقد آتينا موسى عليه السلام هذا العبء الذي أنت بسبيله، فلا تمتر أنك تلقى ما لقي هو من المحنة بالناس، وكأن الآية تسلية لمحمد صلى الله عليه وسلم. ونقل عن فرقة: أن الضمير في {لقائه} عائد على الكتاب، ثم وجهه بقوله:", "qawaid": [], "tabi": ""}], "tags": {"m": {"3": [["ابن عطية", "w"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "معنى: {يمشون}", "mawsua": {"taliq": 5179, "masala": "معنى: {يمشون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون للمخاطبين بالبينة المحتج عليهم", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون للمهلكين", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5179, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 82", "qawl": "", "nass": "أن يكون للمخاطبين بالبينة المحتج عليهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "تأويل: ﴿ويقولون متى هذا الفتح إن كنتم صادقين قل يوم الفتح لا ينفع الذين كفروا إيمانهم ولا هم ينظرو﴾", "tabari": {"page": "18/644", "sarih": 0, "tarjih": "والصواب من القول في ذلك: قول من قال: معناه: ويقولون متى يجيء هذا الحكم بيننا وبينكم؟ يعنون العذاب. يدل على أن ذلك معناه قوله: ﴿قل يوم الفتح لا ينفع الذين كفروا إيمانهم ولا هم ينظرون﴾. ولا شك أن الكفار قد جعل الله التوبة قبل فتح مكة وبعده، ولو كان معنى قوله: ﴿متى هذا الفتح﴾ على ما قاله من قال: يعني به فتح مكة - لكان لا توبة لمن أسلم من المشركين بعد فتح مكة، [ولا شك أن الله قد تاب على بشر كثير من المشركين بعد فتح مكة] ، ونفعهم بالإيمان به وبرسوله؛ فمعلوم بذلك صحة ما قلنا من التأويل وفساد ما خالفه. وقوله: ﴿إن كنتم صادقين﴾. يعني: إن كنتم صادقين في الذي تقولون من أنا معاقبون على تكذيبنا محمدا، وعبادتنا الآلهة والأوثان.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ويقول هؤلاء المشركون بالله [لك، يا محمد] : ﴿متى هذا الفتح﴾.", "taqdim": 1, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [61548]}, {"n": 2, "t": "بل عنى بذلك فتح مكة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5183, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 644", "qawl": "الأول", "nass": "يدل على أن ذلك معناه قوله: {قل يوم الفتح لا ينفع الذين كفروا إيمانهم ولا هم ينظرون}، ولا شك أن الكفار قد كان جعل الله لهم التوبة قبل فتح مكة وبعده، ولو كان معنى قوله: {متى هذا الفتح} على ما قاله من قال: يعني به: فتح مكة؛ لكان لا توبة لمن أسلم من المشركين بعد فتح مكة، ولا شك أن الله قد تاب على بشر كثير من المشركين بعد فتح مكة، ونفعهم بالإيمان به وبرسوله، فمعلوم بذلك صحة ما قلنا من التأويل، وفساد ما خالفه", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5183, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "رجحه", "kind": "ترجيح", "ref": "7/ 83", "qawl": "", "nass": "وهو أقوى الأقوال", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5183, "mi": 1, "aya": 28, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 109", "qawl": "الأول", "nass": "ومن زعم أن المراد من هذا الفتح: فتح مكة؛ فقد أبعد النجعة، وأخطأ فأفحش، فإن يوم الفتح قد قبل رسول الله صلى الله عليه وسلم إسلام الطلقاء، وقد كانوا قريبا من ألفين، ولو كان المراد فتح مكة لما قبل إسلامهم؛ لقوله: {قل يوم الفتح لا ينفع الذين كفروا إيمانهم ولا هم ينظرون}، وإنما المراد: الفتح الذي هو القضاء والفصل، كقوله تعالى: {فافتح بيني وبينهم فتحا ونجني ومن معي من المؤمنين} [الشعراء: 118]، وكقوله: {قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم} [سبأ: 26]، وقال تعالى: {واستفتحوا وخاب كل جبار عنيد} [إبراهيم: 15]، وقال: {وكانوا من قبل يستفتحون على الذين كفروا} [البقرة: 89]، وقال: {إن تستفتحوا فقد جاءكم الفتح} [الأنفال: 19]", "qawaid": ["التاريخ والواقع", "القرآن والنظائر"], "tabi": ""}, {"taliq": 5183, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "الثاني", "nass": "وهذا ضعيف، يرده الإخبار بأن الكفرة لا ينفعهم الإيمان، فلم يبق أن يكون الفتح إما حكم الآخرة، وهو قول مجاهد، وإما فصل الدنيا كبدر ونحوه", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["032_006_1.png"], "pages": [416], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5183, "masala": "معنى: «الفتح»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الحكم", "ashab": "", "athar": []}, {"n": 2, "t": "عني به: فتح مكة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]], "2": [["ابن عطية", "d"]]}, "t": {"2": [["ابن عطية", "d"]]}, "gen": [["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "ابن عطية": ["لم يذكر مستندًا"], "ابن كثير": ["التاريخ والواقع", "القرآن والنظائر"]}, "rulesD": {"ابن عطية": ["ظاهر الآية ولفظها", "الدلالة العقلية"]}}}], "extra": [], "others": {"8": [{"id": 5162, "kinds": "غيره", "text": "لم يذكر ابنُ جرير 18/ 600 - 601 في معنى: {ثُمَّ جَعَلَ نَسْلَهُ مِن سُلالَةٍ مِن ماءٍ مَهِينٍ} سوى قول ابن عباس، وقتادة من طريق سعيد، ومجاهد من طريق ابن أبي نجيح.", "mawaqif": []}], "10": [{"id": 5163, "kinds": "توجيه", "text": "وجَّه ابنُ جرير (18/ 602) قراءة الحسن أنها: «بمعنى: أنتَنّا، مِن قولهم: صَلَّ اللحم وأصَلَّ، إذا أنتَنَ».", "mawaqif": [{"taliq": 5163, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "18/ 602", "qawl": "", "nass": "بمعنى: أنتنا، من قولهم: صل اللحم وأصل، إذا أنتن", "qawaid": [], "tabi": ""}]}], "11": [{"id": 5164, "kinds": "نقل", "text": "ذكر ابنُ كثير (11/ 93) في تفسير قوله تعالى: {قُلْ يَتَوَفّاكُمْ مَلَكُ المَوْتِ الَّذِي وُكِّلَ بِكُمْ} أن الظاهر من الآية أن ملك الموت شخص معيَّن من الملائكة، وقد سُمِّيَ في بعض الآثار بعزرائيل، ثم قال: «وهو المشهور، قاله قتادة وغير واحد، وله أعوان».", "mawaqif": [{"taliq": 5164, "mi": 0, "aya": 11, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 93", "qawl": "", "nass": "وهو المشهور، قاله قتادة وغير واحد، وله أعوان", "qawaid": [], "tabi": ""}]}], "12": [{"id": 5165, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 605) في معنى: {ناكِسُو رُءُوسِهِمْ} سوى قول ابن زيد.", "mawaqif": []}], "15": [{"id": 5166, "kinds": "تعليق،نقل،استدلال", "text": "نقل ابنُ عطية (7/ 74) عن ابن عباس أنّ السجود في قوله تعالى: {إنَّما يُؤْمِنُ بِآياتِنا الَّذِينَ إذا ذُكِّرُوا بِها خَرُّوا سُجَّدًا} بمعنى: الركوع، ثم علَّق عليه بقوله: «وقد روي عن ابن جريج، ومجاهد: أنّ هذه الآية نزلت بسبب قوم من المنافقين كانوا إذا أُقِيمت الصلاة خرجوا من المسجد. فكأن الركوع يقصد من هذا، ويلزم على هذا أن تكون الآية مدنية، وأيضًا فمن مذهب ابن عباس أن القارئ للسجدة يركع، واستدل بقوله: {وخَرَّ راكِعًا وأَنابَ} [ص: 24]».", "mawaqif": [{"taliq": 5166, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 74", "qawl": "", "nass": "وقد روي عن ابن جريج، ومجاهد: أن هذه الآية نزلت بسبب قوم من المنافقين كانوا إذا أقيمت الصلاة خرجوا من المسجد. فكأن الركوع يقصد من هذا، ويلزم على هذا أن تكون الآية مدنية، وأيضا فمن مذهب ابن عباس أن القارئ للسجدة يركع، واستدل بقوله: {وخر راكعا وأناب} [ص: 24]", "qawaid": [], "tabi": ""}]}], "16": [{"id": 5167, "kinds": "نقد،بيان", "text": "بيَّن ابنُ عطية (7/ 76) أن قول الضحاك قولٌ حسن، غير أنه انتقده مستندًا إلى لفظ الآية قائلًا: «يُبْعِده لفظ الآية».", "mawaqif": [{"taliq": 5167, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 76", "qawl": "الضحاك قول", "nass": "يبعده لفظ الآية", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "21": [{"id": 5173, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 634) في معنى: {لَعَلَّهُمْ يَرْجِعُونَ} سوى قول ابن مسعود، وأبي العالية، وقتادة.", "mawaqif": []}], "22": [{"id": 5174, "kinds": "نقد،توجيه،نقل", "text": "نقل ابنُ عطية (7/ 80) عن ابن جرير أثر يزيد بن رفيع أن المقصود بقوله تعالى: {إنّا مِنَ المُجْرِمِينَ مُنْتَقِمُونَ} أهل القدر، ووجَّهه بقوله: «يريد: القائلين بأن أفعال العبد من قبله». ثم انتقد استدلال يزيد بقوله تعالى: {إنَّ المُجْرِمِينَ فِي ضَلالٍ وسُعُرٍ} إلى قوله: {إنّا كُلَّ شَيْءٍ خَلَقْناهُ بِقَدَرٍ} [القمر: 47 - 49] على المعنى الذي ذهب إليه، فقال: «وفي هذا المنزع من البُعْد ما لا خفاء به».", "mawaqif": [{"taliq": 5174, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 80", "qawl": "", "nass": "يريد: القائلين بأن أفعال العبد من قبله", "qawaid": [], "tabi": ""}]}], "23": [{"id": 5175, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 636) في معنى: {فَلا تَكُنْ فِي مِرْيَةٍ مِن لِقائِهِ} سوى حديث ابن عباس رضي الله عنهما.", "mawaqif": []}, {"id": 5177, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 637) في معنى: {وجَعَلْناهُ هُدًى لِبَنِي إسْرائِيلَ} سوى قول قتادة.", "mawaqif": []}], "25": [{"id": 5178, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 81) أنّ قوله تعالى: {إنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ القِيامَةِ} حُكْمٌ يعمُّ جميع الخَلْق. ونقل عن بعض المتأوِّلين أنهم ذهبوا إلى تخصيص الضمير، ثم انتقد ذلك بقوله: «وذلك ضعيف».", "mawaqif": [{"taliq": 5178, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 81", "qawl": "", "nass": "وذلك ضعيف", "qawaid": [], "tabi": ""}]}], "27": [{"id": 5180, "kinds": "نقد،بيان", "text": "بيَّن ابنُ عطية (7/ 82 - 83) بأن معنى: {الجُرُز}: الأرض العاطشة التي قد أكلت نباتها مِن العطش والقيظ. ثم انتقد قول من قال: بأنها الأرض التي لا تُنبِت قائلًا: «ومَن عبَّر عنها بأنها الأرض التي لا تُنْبِت فإنها عبارة غير مخلصة».", "mawaqif": [{"taliq": 5180, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 82 - 83", "qawl": "", "nass": "ومن عبر عنها بأنها الأرض التي لا تنبت فإنها عبارة غير مخلصة", "qawaid": [], "tabi": ""}]}, {"id": 5181, "kinds": "تعليق", "text": "علَّق ابنُ كثير (11/ 107) على قول من قال بأن {الأرض الجرز} هي: أرض مصر، بقوله: «وليس المراد من قوله: {إلى الأَرْضِ الجُرُزِ} أرض مصر فقط، بل هي بعض المقصود، وإن مثَّل بها كثير من المفسرين فليست المقصودة وحدها، ولكنَّها مرادةٌ قَطْعًا من هذه الآية، فإنها في نفسها أرض رخوة غليظة، تحتاج من الماء ما لو نزل عليها مطرًا لتهدَّمت أبنيتها، فيسوق الله إليها النيل بما يتحمله من الزيادة الحاصلة من أمطار بلاد الحبشة، وفيه طين أحمر، فيغشى أرض مصر، وهي أرض سبخة مرملة، محتاجة إلى ذلك الماء، وذلك الطين أيضًا؛ ليَنبُتَ الزرع فيه، فيستغلون كل سنة على ماء جديد ممطور في غير بلادهم، وطين جديد من غير أرضهم، فسبحان الحكيم الكريم المنان، المحمود ابتداء».", "mawaqif": [{"taliq": 5181, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 107", "qawl": "", "nass": "وليس المراد من قوله: {إلى الأرض الجرز} أرض مصر فقط، بل هي بعض المقصود، وإن مثل بها كثير من المفسرين فليست المقصودة وحدها، ولكنها مرادة قطعا من هذه الآية، فإنها في نفسها أرض رخوة غليظة، تحتاج من الماء ما لو نزل عليها مطرا لتهدمت أبنيتها، فيسوق الله إليها النيل بما يتحمله من الزيادة الحاصلة من أمطار بلاد الحبشة، وفيه طين أحمر، فيغشى أرض مصر، وهي أرض سبخة مرملة، محتاجة إلى ذلك الماء، وذلك الطين أيضا؛ لينبت الزرع فيه، فيستغلون كل سنة على ماء جديد ممطور في غير بلادهم، وطين جديد من غير أرضهم، فسبحان الحكيم الكريم المنان، المحمود ابتداء", "qawaid": [], "tabi": ""}]}, {"id": 5182, "kinds": "تعليق", "text": "علَّق ابنُ كثير (11/ 108) على قول الضحاك، وعكرمة، وقتادة، والسدي، وابن زيد بقوله: «وهذا كقوله: {وآيَةٌ لَهُمُ الأرْضُ المَيْتَةُ أحْيَيْناها وأَخْرَجْنا مِنها حَبًّا فَمِنهُ يَأْكُلُونَ * وجَعَلْنا فِيها جَنّاتٍ مِن نَخِيلٍ وأَعْنابٍ وفَجَّرْنا فِيها مِنَ العُيُونِ * لِيَأْكُلُوا مِن ثَمَرِهِ وما عَمِلَتْهُ أيْدِيهِمْ أفَلا يَشْكُرُونَ} [يس: 33 - 35]».", "mawaqif": [{"taliq": 5182, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 108", "qawl": "الضحاك", "nass": "وهذا كقوله: {وآية لهم الأرض الميتة أحييناها وأخرجنا منها حبا فمنه يأكلون * وجعلنا فيها جنات من نخيل وأعناب وفجرنا فيها من العيون * ليأكلوا من ثمره وما عملته أيديهم أفلا يشكرون} [يس: 33 - 35]", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5184, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 645) في معنى: {قُلْ يَوْمَ الفَتْحِ لا يَنْفَعُ الَّذِينَ كَفَرُوا إيمانُهُمْ} سوى قول ابن زيد، ومجاهد.", "mawaqif": []}], "30": [{"id": 5185, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 646) في معنى: {فَأَعْرِضْ عَنْهُمْ وانْتَظِرْ إنَّهُمْ مُنْتَظِرُونَ} سوى قول قتادة.", "mawaqif": []}]}, "athar": {"61458": {"num": 61458, "aya": 21, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق ابن أبي ليلى- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: مصائب الدنيا، والروم، والبطشة، والدخان."}, "61459": {"num": 61459, "aya": 21, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق مجاهد- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: يوم بدر."}, "61460": {"num": 61460, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: يوم بدر."}, "61461": {"num": 61461, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: سِنُون أصابتهم."}, "61462": {"num": 61462, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص- في قوله: {العَذابِ الأَدْنى}، قال: سنون أصابت قومًا قبلكم."}, "61463": {"num": 61463, "aya": 21, "qail": "الحسن بن علي", "tabaqa": "صحابي", "bab": "", "text": "عن الحسن بن علي -من طريق عوف، عمَّن حدَّثه- أنه قال: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: القتل بالسيف صَبْرًا."}, "61464": {"num": 61464, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق شبيب، عن عكرمة- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى دُونَ العَذابِ الأَكْبَرِ}، قال: الحدود."}, "61465": {"num": 61465, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، يقول: مصائب الدنيا، وأسقامها، وبلاؤها مما يبتلي الله بها العباد حتى يتوبوا."}, "61466": {"num": 61466, "aya": 21, "qail": "عبد الله بن الحارث بن نوفل", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن الحارث بن نوفل -من طريق عوف- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: القتل بالسيف، كل شيء وعد الله هذه الأمة مِن العذاب الأدنى إنما هو السيف."}, "61467": {"num": 61467, "aya": 21, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرياحي -من طريق الربيع- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: المصائب في الدنيا."}, "61468": {"num": 61468, "aya": 21, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق جرير، عن منصور- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى دُونَ العَذابِ الأَكْبَرِ}، قال: أشياء يُصابون بها في الدنيا."}, "61469": {"num": 61469, "aya": 21, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق سفيان، عن منصور- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى دُونَ العَذابِ الأَكْبَرِ}، قال: سنون أصابتهم."}, "61470": {"num": 61470, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: عذاب الدنيا، وعذاب القبر."}, "61471": {"num": 61471, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: القتل والجوع لقريش في الدنيا."}, "61474": {"num": 61474, "aya": 21, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق الحسن بن دينار- قال: {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى} العذاب الأدنى بالسيف يوم بدر."}, "61475": {"num": 61475, "aya": 21, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}: أي: مصيبات الدنيا."}, "61476": {"num": 61476, "aya": 21, "qail": "الحسن", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن -من طريق معمر- {العَذابِ الأَدْنى}: عقوبات الدنيا."}, "61477": {"num": 61477, "aya": 21, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة ="}, "61481": {"num": 61481, "aya": 21, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {ولَنُذِيقَنَّهُمْ مِنَ العَذابِ الأَدْنى}، قال: العذاب الأدنى: عذاب الدنيا."}, "61482": {"num": 61482, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- في قوله: {دُونَ العَذابِ الأَكْبَرِ}، قال: يوم القيامة."}, "61483": {"num": 61483, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح-: العذاب الأكبر يوم القيامة في الآخرة."}, "61484": {"num": 61484, "aya": 21, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- {دُونَ العَذابِ الأَكْبَرِ}: يوم القيامة."}, "61485": {"num": 61485, "aya": 21, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {دُونَ العَذابِ الأَكْبَرِ}: يوم القيامة."}, "61487": {"num": 61487, "aya": 21, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {دُونَ العَذابِ الأَكْبَرِ}، قال: العذاب الأكبر: عذاب الآخرة."}, "61489": {"num": 61489, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- في قوله: {لَعَلَّهُمْ يَرْجِعُونَ}، قال: لعلَّ مَن بقي منهم أن يتوب فيرجع."}, "61490": {"num": 61490, "aya": 21, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- {لَعَلَّهُمْ يَرْجِعُونَ}، قال: يتوبون."}, "61491": {"num": 61491, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {لَعَلَّهُمْ يَرْجِعُونَ}، قال: يتوبون."}, "61492": {"num": 61492, "aya": 21, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرياحي -من طريق الربيع- {لَعَلَّهُمْ يَرْجِعُونَ}، قال: يتوبون."}, "61493": {"num": 61493, "aya": 21, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {لَعَلَّهُمْ يَرْجِعُونَ}، قال: يتوبون."}, "61494": {"num": 61494, "aya": 21, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {لَعَلَّهُمْ يَرْجِعُونَ}، قال: يتوبون."}, "61495": {"num": 61495, "aya": 21, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة-، مثله."}, "61502": {"num": 61502, "aya": 22, "qail": "يزيد بن رفيع", "tabaqa": "", "bab": "تفسير الآية", "text": "عن يزيد بن رُفَيْع -من طريق مروان بن سُفَيْح- قال: إنّ قول الله في القرآن: {إنّا مِنَ المُجْرِمِينَ مُنْتَقِمُونَ} هم أصحاب القدَر. ثم قرأ: {إنَّ المُجْرِمِينَ فِي ضَلالٍ وسُعُرٍ} إلى قوله: {إنّا كُلَّ شَيْءٍ خَلَقْناهُ بِقَدَرٍ} [القمر: 47 - 49]."}, "61548": {"num": 61548, "aya": 28, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: قال الصحابة: إنّ لنا يومًا يوشك أن نستريح فيه، ونَتَنَعَّم فيه. فقال المشركون: متى هذا الفتح إن كنتم صادقين}. فنزلت."}, "61254": {"num": 61254, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {يُدَبِّرُ الأَمْرَ}، قال: هذا في الدنيا."}, "61255": {"num": 61255, "aya": 5, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- قال: يقضي أمرَ كل شيء ألف سنة إلى الملائكة، ثم كذلك حتى تمضي ألف سنة، ثم يقضي أمر كل شيء ألفًا، ثم كذلك أبدًا."}, "61259": {"num": 61259, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي-: تعرج الملائكةُ في يوم مقداره ألف سنة."}, "61260": {"num": 61260, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي الحارث، عن عكرمة-: {ثُمَّ يَعْرُجُ إلَيْهِ فِي يَوْمٍ} من أيامكم هذه، ومسيرة ما بين السماء والأرض خمسمائة عام."}, "61261": {"num": 61261, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سِماك، عن عكرمة- في قوله: {يُدَبِّرُ الأَمْرَ مِنَ السَّماءِ إلى الأَرْضِ ثُمَّ يَعْرُجُ إلَيْهِ فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ}، قال: مِن الأيام الستة التي خلق الله فيها السموات والأرض."}, "61262": {"num": 61262, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {كانَ مِقْدارُهُ ألْفَ سَنَةٍ}، قال: لا ينتصف النهار في مقدار يومٍ مِن أيام الدنيا في ذلك اليوم حتى يُقضى بين العباد، فينزل أهل الجنة الجنة، وأهل النار النار، ولو كان إلى غيره لم يفرغ مِن ذلك في خمسين ألف سنة."}, "61264": {"num": 61264, "aya": 5, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي بشر- {وإن يومًا عند ربك كألف سنة}، قال: مِن أيام الآخرة."}, "61265": {"num": 61265, "aya": 5, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج-: يقضى أمر كل شيء ألف سنة إلى الملائكة، ثم كذلك حتى تمضي ألف سنة، ثم يقضى أمر كل شيء ألفًا، ثم كذلك أبدًا، قال: {يَوْمٍ كانَ مِقْدارُهُ} قال: اليوم: أن يُقال لما يقضى إلى الملائكة ألف سنة: كن. فيكون، ولكن سماه يومًا، وقوله: {وإنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمّا تَعُدُّونَ} [الحج: 47]. قال: هو هو سواء."}, "61266": {"num": 61266, "aya": 5, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ}: يعني بذلك: نزول الأمر من السماء إلى الأرض، ومن الأرض إلى السماء في يوم واحد، وذلك مقدار ألف سنة؛ لأنّ ما بين السماء إلى الأرض مسيرة خمسمائة عام."}, "61267": {"num": 61267, "aya": 5, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جويبر- {ثُمَّ يَعْرُجُ إلَيْهِ فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ مِمّا تَعُدُّونَ}، قال: تعرج الملائكة إلى السماء ثم تنزل في يوم مِن أيامكم هذه، وهو مسيرة ألف سنة."}, "61268": {"num": 61268, "aya": 5, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق عبيد- يقول في قوله: {فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ مِمّا تَعُدُّونَ}: يعني: هذا اليوم مِن الأيام الستة التي خلق الله فيهن السماوات والأرض وما بينهما."}, "61272": {"num": 61272, "aya": 5, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {يُدَبِّرُ الأَمْرَ}، قال: ينحدر الأمر من السماء إلى الأرض، ويصعد مِن الأرض إلى السماء في يوم واحد مقداره ألف سنة في السير؛ خمسمائة حين ينزل، وخمسمائة حين يعرج."}, "61273": {"num": 61273, "aya": 5, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ مِمّا تَعُدُّونَ}: مقدار مسيرِهِ في ذلك اليوم ألف سنة مما تعدون من أيامكم من أيام الدنيا؛ خمسمائة سنة نزوله، وخمسمائة سنة صعوده، فذلك ألف سنة."}, "61278": {"num": 61278, "aya": 5, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ثُمَّ يَعْرُجُ إلَيْهِ فِي يَوْمٍ كانَ مِقْدارُهُ ألْفَ سَنَةٍ مِمّا تَعُدُّونَ}، قال: قال بعض أهل العلم: مقدار ما بين الأرض حين يعرج إليه إلى أن يبلغ عروجه ألف سنة، هذا مقدار ذلك المعراج في ذلك اليوم حين يعرج فيه."}, "61282": {"num": 61282, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عكرمة- أنّه كان يقرؤها: {الَّذِي أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}."}, "61283": {"num": 61283, "aya": 7, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن ابن عباس، عن النبي صلى الله عليه وسلم، في قوله: {أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}، قال: «أما إنّ إسْت القِردة ليس بحسنة، ولكنه أحْكَمَ خلقَها»."}, "61284": {"num": 61284, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- {الَّذِي أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}، قال: أما إن إست القردة ليست بحسنة، ولكنه أحكم خلقها."}, "61285": {"num": 61285, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}، قال: صورته."}, "61286": {"num": 61286, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}: فجعل الكلب في خلْقه حسنًا."}, "61287": {"num": 61287, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}، قال: أحسن خلْق كل شيء؛ القبيح والحسن، والعقارب والحيات، وكل شيء مما خلق، وغيره لا يُحسِن شيئًا من ذلك."}, "61288": {"num": 61288, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق خصيف- في قوله: «أحْسَنَ كُلَّ شَيْءٍ خَلْقَهُ»، قال: أتقن، لم يُرَكِّب الإنسان في صورة الحمار، ولا الحمار في صورة الإنسان."}, "61289": {"num": 61289, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق الأعرج- قال: هو مثل {أعْطى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدى} [طه: 50]، قال: فلم يجعل خلق البهائم في خلق الناس، ولا خلق الناس في خلق البهائم، ولكن خلَق كلَّ شيء فقدَّره تقديرًا."}, "61290": {"num": 61290, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {الَّذِي أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}: أتقن كل شيء خلقه."}, "61292": {"num": 61292, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله تعالى: {الَّذِي أحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ}، قال: أحسن خلْق كل شيء."}, "61296": {"num": 61296, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {وبَدَأَ خَلْقَ الإنْسانِ مِن طِينٍ}، قال: آدم."}, "61297": {"num": 61297, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وبَدَأَ خَلْقَ الإنْسانِ}: وهو آدم."}, "61364": {"num": 61364, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: أُنزِلت في صلاة العشاء الآخرة، كان أصحاب رسول الله صلى الله عليه وسلم لا ينامون حتى يصلوها."}, "61365": {"num": 61365, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك -من طريق يحيى بن سعيد-: أنّ هذه الآية: {تَتَجافى جنُوبهم عَن المضاجِع} نزلت في انتظار الصلاة التي تدعى: العتمة."}, "61366": {"num": 61366, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك، قال: نزلت: {تَتَجافى جنُوبهم عَن المضاجِع} في صلاة العشاء."}, "61367": {"num": 61367, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك -من طريق أبان- قال: ما رأيتُ رسولَ الله صلى الله عليه وسلم راقدًا قطُّ قبل العشاء، ولا متحدِّثًا بعدها؛ فإن هذه الآية نزلت في ذلك: {تَتَجافى جنُوبهم عَن المضاجِع}."}, "61368": {"num": 61368, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك، قال: نزلت فينا معاشر الأنصار، كنا نُصَلِّي المغرب فلا نرجع إلى رحالنا حتى نصلي العشاء مع النبي صلى الله عليه وسلم؛ فنزلت فينا: {تَتَجافى جنُوبهم عَن المضاجِع} الآية."}, "61369": {"num": 61369, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك -من طريق مالك بن دينار- أنّه سأله عن هذه الآية: {تَتَجافى جنُوبهم عَن المضاجِع}. قال: كان قومٌ مِن أصحاب رسول الله صلى الله عليه وسلم مِن المهاجرين الأولين يصلون المغرب، ويصلون بعدها إلى عشاء الآخرة؛ فنزلت هذه الآية فيهم."}, "61370": {"num": 61370, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك -من طريق أبان بن أبي عياش- قال: كانوا يتناومون إذا أمسوا مِن قبل أن تفترض صلاة العشاء، فلمّا فُرضت جعلوا لا ينامون حتى يصلوا، فشق ذلك عليهم؛ فنزلت: {تَتَجافى جُنُوبُهُمْ عَنِ المَضاجِعِ} حتى أتم الآية."}, "61378": {"num": 61378, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، أنّ النبي صلى الله عليه وسلم قال: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: «هم الذي لا ينامون قبل العشاء». فأثنى عليهم، فلمّا ذكر ذلك جعل الرجل يعتزل فراشه مخافة أن تغلبه عينه، فَوَقْتُها قبل أن ينام الصغير، ويكسل الكبير."}, "61379": {"num": 61379, "aya": 16, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن ابن عباس، قال: قال رسول الله صلى الله عليه وسلم: «مَن صلّى أربعًا بعد المغرب مِن قبل أن يُكَلِّم أحدًا كان أفضل مِن قيام نصف ليلة، وهي التي يقول الله تعالى: {كانُوا قَلِيلًا مِنَ اللَّيْلِ ما يَهْجَعُونَ} [الذاريات: 17]، وهي التي يقول الله تعالى: {تَتَجافى جُنُوبُهُمْ عَنِ المضاجِعِ}، وهي التي يقول الله تعالى: {ودَخَلَ المَدِينَةَ عَلى حِينِ غَفْلَةٍ مِن أهْلِها} [القصص: 15]. ومَن صلّى أربعًا بعد عشاء الآخرة كأنما صلى هو في المسجد الأقصى، وكأنّما وافق ليلة القدر. ومَن صلى أربعًا قبل الظهر وأربعًا بعدها حرَّمه الله عن النار أن تأكله أبدًا. ومن صلى أربعًا قبل العصر غفر الله له ألبتة»."}, "61380": {"num": 61380, "aya": 16, "qail": "مجاهد", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد، عن ابن عباس، قال: ذكر النبي صلى الله عليه وسلم قيام الليل، وفاضت عيناه، فقرأ: {تتجافى جنوبهم عن المضاجع}."}, "61381": {"num": 61381, "aya": 16, "qail": "مجاهد", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد -من طريق أبي يحيى- قال: ذكر رسولُ الله صلى الله عليه وسلم قيام الليل، ففاضت عيناه حتى تحادرت دموعُه، فقال: {تَتَجافى جنُوبهم عَن المضاجِع}."}, "61385": {"num": 61385, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {تَتَجافى جنُوبهم عَن المضاجِع}، يقول: تتجافى لذكر الله، كلما استيقظوا ذكروا الله؛ إما في الصلاة، وإما في قيام أو قعود أو على جنوبهم، فهم لا يزالون يذكرون الله."}, "61386": {"num": 61386, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أنس بن مالك -من طريق قتادة- في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: كانوا ينتظرون ما بين المغرب والعشاء يُصَلُّون."}, "61387": {"num": 61387, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أنس بن مالك، في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: كانوا لا ينامون حتى يصلوا العشاء."}, "61388": {"num": 61388, "aya": 16, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أنس بن مالك، في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: كانت لا تمر عليهم ليلة إلا أخذوا منها بحظٍّ."}, "61391": {"num": 61391, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: يقومون فيصلون بالليل."}, "61394": {"num": 61394, "aya": 16, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {تَتَجافى جنُوبهم عَن المضاجِع}، قال: قيام الليل."}, "61395": {"num": 61395, "aya": 16, "qail": "عطاء", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عطاء -من طريق طلحة- {تَتَجافى جُنُوبُهُمْ عَنِ المَضاجِعِ}، قال: عن العتمة."}, "61403": {"num": 61403, "aya": 16, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {تَتَجافى جُنُوبُهُمْ عَنِ المَضاجِعِ}، قال: هؤلاء المتهجدون لصلاة الليل."}}, "n_athar": {"0": 15, "1": 4, "3": 9, "4": 3, "5": 26, "6": 2, "7": 18, "8": 8, "9": 3, "10": 12, "11": 19, "12": 5, "13": 6, "14": 7, "15": 4, "16": 52, "17": 26, "18": 9, "19": 2, "20": 4, "21": 41, "22": 5, "23": 15, "24": 11, "25": 2, "26": 5, "27": 12, "28": 4, "29": 8, "30": 7}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});